import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"聊天入口","description":"","frontmatter":{},"headers":[],"relativePath":"zh/channels.md","filePath":"zh/channels.md"}'),o={name:"zh/channels.md"};function n(l,e,r,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="聊天入口" tabindex="-1">聊天入口 <a class="header-anchor" href="#聊天入口" aria-label="Permalink to &quot;聊天入口&quot;">​</a></h1><p>把你的 nanoMuse 放进你已经在用的聊天软件：飞书 / Lark、钉钉、企业微信和 Telegram。在手机上给机器人发消息，回答的就是同一个 Muse——每个聊天对应一个对话，回复边生成边发回来，工具在跑时显示一行状态，审批用一个词或一个按钮回答。标了「推送到这里」的聊天还会收到 Muse 自己主动做的事：问候、提醒、后台任务的结果、它需要你回答的问题。</p><p>不需要公网地址。每家都提供一种由机器人从你的网络内部主动发起的长连接（Telegram 是长轮询），所以运行时放在路由器后面或一台笔记本上就够了。socket 的活由各家自己的 SDK 来干；它们是可选的额外依赖：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[feishu]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # lark-oapi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[dingtalk]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # dingtalk-stream</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[wecom]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # wecom-aibot-sdk-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[channels]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # all three; Telegram needs nothing extra</span></span></code></pre></div><p>Docker 镜像带全了这些。没装 SDK 时，应用会显示要安装的那行命令，开关保持不动。</p><h2 id="where-to-find-it" tabindex="-1">在哪里找到它 <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;在哪里找到它 {#where-to-find-it}&quot;">​</a></h2><ul><li><p><strong>应用</strong>——设置 → 「聊天入口」。每个聊天软件一张卡片：开关、凭据、谁可以和它说话、已配对的聊天和各自的「推送到这里」开关、一个「发一条测试消息」按钮，还有设置步骤和指向厂商控制台的链接。</p></li><li><p><strong>终端</strong>——<code>nanomuse channels status | pending | approve &lt;code&gt; | deny &lt;code&gt; | login feishu [--lark] | test &lt;name&gt;</code>。<code>nanomuse serve</code> 在跑时，这些命令走它的 API；否则它们直接改 <code>&lt;data_dir&gt;/channels/</code> 下的文件，服务器启动时（或按「重新加载」时）读入。</p></li><li><p><strong>API</strong>——<code>GET /api/channels</code>、<code>PUT /api/channels/&lt;name&gt;</code>、<code>POST /api/channels/pairing/&lt;code&gt;/approve|deny</code>、<code>PUT|DELETE /api/channels/&lt;name&gt;/chats/&lt;sender&gt;</code>、<code>POST /api/channels/&lt;name&gt;/test</code>、<code>POST /api/channels/deliver {text}</code>、<code>POST /api/channels/reload</code>，飞书还有 <code>POST /api/channels/feishu/login</code> + <code>GET /api/channels/feishu/login/&lt;device_code&gt;</code>。</p></li><li><p><strong>config.toml</strong>——手工搭的服务器也可以写一张 <code>[channels.&lt;name&gt;]</code> 表：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">channels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">telegram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${TELEGRAM_BOT_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_from = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;123456789&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Telegram user ids that never need a code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">group_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mention&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or &quot;open&quot;</span></span></code></pre></div><p>应用里保存的值按字段优先。在应用里填的密钥进保险库（文件里留的是 <code>{{vault:CHANNEL_TELEGRAM_BOT_TOKEN}}</code>），之后不再显示——密钥字段只告诉你有没有填过。</p></li></ul><h2 id="setting-up-each-app" tabindex="-1">逐个设置 <a class="header-anchor" href="#setting-up-each-app" aria-label="Permalink to &quot;逐个设置 {#setting-up-each-app}&quot;">​</a></h2><p>下面的控制台名称是 2026 年时的叫法；厂商会挪地方。</p><h3 id="feishu-lark" tabindex="-1">飞书 / Lark <a class="header-anchor" href="#feishu-lark" aria-label="Permalink to &quot;飞书 / Lark {#feishu-lark}&quot;">​</a></h3><p>最快的办法：在应用里按「扫码创建机器人」（或运行 <code>nanomuse channels login feishu</code>，国际版加 <code>--lark</code>），用飞书扫码，确认，完成——App ID 和 Secret 已经保存，这个入口随即打开。这是飞书自己为个人智能体提供的扫码建应用流程；它创建出来的应用已经带上机器人能力和长连接事件。</p><p>手动的话，到 <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">https://open.feishu.cn/app</a>（Lark：<a href="https://open.larksuite.com/app" target="_blank" rel="noreferrer">https://open.larksuite.com/app</a>）：</p><ol><li>「创建企业自建应用」→「添加应用能力」→ <strong>机器人</strong>。</li><li>「权限管理」：<code>im:message</code>、<code>im:message.p2p_msg:readonly</code>、<code>im:message.group_at_msg:readonly</code>、<code>im:resource</code>（图片和文件）。</li><li>「事件与回调」：订阅方式选 <strong>长连接</strong>，添加 <code>im.message.receive_v1</code>；回调方式选 <strong>长连接</strong>，添加 <code>card.action.trigger</code>（审批按钮）。</li><li>「凭证与基础信息」：把 <strong>App ID</strong> 和 <strong>App Secret</strong> 复制到应用里；选 <em>feishu</em> 或 <em>lark</em>。「Encrypt Key」和「Verification Token」留空，除非你在控制台里设了。</li><li>「版本管理与发布」→ 创建版本 → 发布。</li></ol><p>回复是带 markdown 正文的可交互卡片；回复流式生成时，卡片原地更新（大约每秒一次）。你的消息上出现一个 👍，表示 Muse 正在处理。群里 @ 它才回答。</p><h3 id="dingtalk" tabindex="-1">钉钉 <a class="header-anchor" href="#dingtalk" aria-label="Permalink to &quot;钉钉 {#dingtalk}&quot;">​</a></h3><p>到 <a href="https://open-dev.dingtalk.com/" target="_blank" rel="noreferrer">https://open-dev.dingtalk.com/</a>：</p><ol><li>「创建应用」（企业内部应用）→「添加应用能力」→ <strong>机器人</strong>。</li><li>消息接收模式：<strong>Stream 模式</strong>。不需要回调地址。</li><li>「凭证与基础信息」：复制 <strong>Client ID</strong>（AppKey）和 <strong>Client Secret</strong>（AppSecret）。</li><li>「权限管理」：机器人发消息的权限（<code>qyapi_robot_sendmsg</code>），这样「推送到这里」的聊天在没有消息可回复时也能写入。</li><li>发布版本；把机器人加进群，或在通讯录里找到它。</li></ol><p>钉钉消息不能编辑，所以回复在写完后一次发出。钉钉群里的机器人只听得到 @ 它的消息。</p><h3 id="wecom" tabindex="-1">企业微信 <a class="header-anchor" href="#wecom" aria-label="Permalink to &quot;企业微信 {#wecom}&quot;">​</a></h3><p>在企业微信管理后台 →「安全与管理」→ <strong>智能机器人</strong>：</p><ol><li>「创建机器人」→ <strong>API 模式</strong>，连接方式选 <strong>长连接</strong>。</li><li>把 <strong>Bot ID</strong> 和 <strong>Secret</strong> 复制到应用里。</li><li>把机器人加进它该听的聊天，或者让大家在通讯录里找到它。</li></ol><p>socket 主机（<code>openws.work.weixin.qq.com</code>）已加进运行时进程的 <code>NO_PROXY</code>；公司的 HTTPS 代理通常带不动它。回复经同一个 socket 流式返回；主动消息（推送）是 markdown。</p><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram {#telegram}&quot;">​</a></h3><ol><li>在 Telegram 里找 <strong>@BotFather</strong>，发 <code>/newbot</code>，把 token 复制到应用里。</li><li>私聊立刻可用。群聊要先把机器人拉进群；BotFather 的「Group Privacy」开着（默认）时，它只听得到 @ 它的消息和对它自己消息的回复，正好对应 <em>mention</em> 策略。</li><li>这台电脑连不上 <code>api.telegram.org</code> 的话，填 <strong>代理</strong>（<code>socks5://…</code> 或 <code>http://…</code>）。</li></ol><p>回复先发出，再在流式生成时原地编辑（超过 Telegram 的 4096 字符上限会拆成几条）。审批是两个内联按钮。</p><h2 id="pairing-who-may-talk-to-the-bot" tabindex="-1">配对：谁可以和机器人说话 <a class="header-anchor" href="#pairing-who-may-talk-to-the-bot" aria-label="Permalink to &quot;配对：谁可以和机器人说话 {#pairing-who-may-talk-to-the-bot}&quot;">​</a></h2><p>找到机器人的人都能给它发消息；Muse 只回答你放进来的人。</p><ul><li>陌生人的第一条私聊只会得到一个<strong>配对码</strong>（六位字母和数字，不含 0/O/1/I，十分钟有效），别的什么都没有——这条消息不会到 Muse。在 设置 → 聊天入口 里通过这个码，或者运行 <code>nanomuse channels approve &lt;code&gt;</code>。对方会收到通知，此后的消息就通了。</li><li><strong>免配对的 ID</strong>（<code>allow_from</code>）：不需要配对码的厂商用户 id。单独一个 <code>*</code> 放行所有人——只适合别人都找不到的机器人。</li><li><strong>群</strong>：群里的陌生人被静静忽略（群里不发配对码）。已配对的人在群里的消息，机器人被 @ 时才回答（<code>group_policy = &quot;mention&quot;</code>），或者每条都回（<code>&quot;open&quot;</code>）。群本身是一个独立的对话；每一行都带着发送者的名字。</li><li>在应用里<strong>移除</strong>一个已配对的聊天（或从 <code>pairing.json</code> 里删掉）；对方的下一条消息会收到新的配对码。</li></ul><p>配对关系和配对码存在 <code>&lt;data_dir&gt;/channels/pairing.json</code>——在数据目录，不在工作区，所以智能体自己的文件工具改不了谁可以和它说话。</p><h2 id="how-a-chat-maps-to-the-muse" tabindex="-1">聊天怎么对应到 Muse <a class="header-anchor" href="#how-a-chat-maps-to-the-muse" aria-label="Permalink to &quot;聊天怎么对应到 Muse {#how-a-chat-maps-to-the-muse}&quot;">​</a></h2><p>每个聊天是智能体的一个对话，id 是 <code>channel-&lt;app&gt;-&lt;chat id&gt;</code>，在应用抽屉里的标题是「飞书 · Ann」/「Telegram · Team」。来自聊天的消息和在应用里打的字走同一个入口，所以其他一切——记忆、目标、哨兵（Sentinel）、技能——都是同一个 Muse。附件（照片、文件、语音）保存在工作区的 <code>attachments/</code> 下，并附在消息上。</p><p>运行进行时：</p><ul><li>文字随着模型的输出流进回复（厂商允许编辑的地方）；</li><li>正在运行的工具在同一条消息里显示为一行斜体短句（「正在搜索网页」「正在运行命令」），直到被文字替换；</li><li>哨兵要求的<strong>审批</strong>会到聊天里：飞书和 Telegram 是带「允许」/「拒绝」按钮的卡片，钉钉和企业微信是一条要你回一个词的消息。<code>allow</code>、<code>yes</code>、<code>ok</code>、<code>允许</code>、<code>同意</code> 是允许一次；<code>deny</code>、<code>no</code>、<code>拒绝</code>、<code>不行</code> 是拒绝。这个决定和在应用里按卡片是一样的；</li><li>运行产生的文件（构件事件）在运行结束时发出；</li><li>Muse 提出的<strong>问题</strong>会送到聊天里，你的下一行就是回答。</li></ul><p>语言跟随 <code>agent.language</code>：<code>zh</code> 时这些短句是中文，<code>en</code> 是英文，<code>auto</code> 两种都有。</p><h2 id="deliver-here" tabindex="-1">推送到这里 <a class="header-anchor" href="#deliver-here" aria-label="Permalink to &quot;推送到这里 {#deliver-here}&quot;">​</a></h2><p>给一个已配对的聊天打开「推送到这里」，它还会收到 Muse 没被要求也会做的事——也就是手机 App 变成通知的那些事件：后台运行的最后一句话（安静的除外）、等待中的审批（可以直接在聊天里回答）、需要你的问题。一个 Muse 可以推送到好几个聊天；每个聊天自己决定。<code>POST /api/channels/deliver {&quot;text&quot;: …}</code> 给它们全部发一行字——脚本或提醒里用得上。</p><h2 id="security" tabindex="-1">安全 <a class="header-anchor" href="#security" aria-label="Permalink to &quot;安全 {#security}&quot;">​</a></h2><ul><li>密钥进保险库，从不经 API 回传；设置文件里只有占位符。日志里是厂商的错误原文，不含凭据。</li><li>只有已配对或在放行名单里的人能到达 Muse；陌生人得到一个配对码，在群里则是沉默。审批卡片上的按钮，只有已配对的人按才算数。</li><li>来自聊天的审批是一次性的决定，理由是「来自飞书」（等等）——聊天里不会记住任何东西。</li><li>聊天入口的数据放在数据目录，智能体够不着。</li><li>连接都是向外发起的；不开端口，不涉及公网地址。</li></ul><h2 id="troubleshooting" tabindex="-1">排错 <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;排错 {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你看到的</th><th>意思</th></tr></thead><tbody><tr><td><strong>未安装</strong></td><td>运行 nanoMuse 的机器上缺 SDK：运行显示的那行（<code>pip install &#39;nanomuse[feishu]&#39;</code>），再把这个入口重新打开</td></tr><tr><td><strong>还缺设置</strong></td><td>有必填项是空的；卡片会写明是哪一项</td></tr><tr><td><strong>出错</strong>，后面是厂商的原话</td><td>凭据被拒，或连不上厂商；改好后关掉再开，或再按一次「保存」</td></tr><tr><td>机器人在群里不回答</td><td>群策略是 <em>mention</em> 而机器人没被 @；或者发送者没有配对（群里从不显示配对码）</td></tr><tr><td>飞书有回复，但没有表情回应 / 卡片没有按钮</td><td>缺 <code>im:message.group_at_msg:readonly</code> / <code>im:resource</code>，或者 <code>card.action.trigger</code> 没有放在长连接上</td></tr><tr><td>飞书：「app secret invalid」</td><td>App Secret 在控制台里被重新生成了；贴新的</td></tr><tr><td>钉钉连上了但收不到东西</td><td>机器人的接收模式不是 <em>Stream</em>，或者版本没有发布</td></tr><tr><td>企业微信：代理后面连接出错</td><td>socket 绕开了 <code>HTTPS_PROXY</code>；主机必须能直连</td></tr><tr><td>Telegram：<code>Conflict: terminated by other getUpdates request</code></td><td>同一个 token 在两处轮询（另一个运行时，或一个 webhook）；只留一个</td></tr><tr><td>配对码一直来</td><td>十分钟内通过一个；<code>nanomuse channels pending</code> 列出全部</td></tr><tr><td><code>nanomuse channels …</code> 说服务器拒绝了 token</td><td>config.toml 里的 <code>server.token</code> 和正在跑的服务器的不一致；或者用同一个 <code>--config</code> 运行它</td></tr></tbody></table><p><code>nanomuse channels status --json</code> 输出的和应用看到的是同一份。</p>`,41)])])}const k=t(o,[["render",n]]);export{g as __pageData,k as default};
